package com.hrflow.platform.employee;
import com.hrflow.platform.common.ApiModels.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/employees") @RequiredArgsConstructor public class EmployeeController {private final EmployeeService service;
 @PostMapping @ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAnyRole('ADMIN','HR')")EmployeeView create(@Valid @RequestBody EmployeeInput i){return service.create(i);}
 @GetMapping @PreAuthorize("hasAnyRole('ADMIN','HR')")Page<EmployeeView> list(@RequestParam(required=false)String search,@RequestParam(required=false)Long departmentId,@RequestParam(required=false)Boolean active,@PageableDefault(sort="lastName")Pageable p){return service.list(search,departmentId,active,p);}
 @GetMapping("/me")EmployeeView me(Authentication a){return service.me(a.getName());}@GetMapping("/{id}")EmployeeView get(@PathVariable Long id,Authentication a){return service.get(id,a);}
 @PutMapping("/{id}")@PreAuthorize("hasAnyRole('ADMIN','HR')")EmployeeView update(@PathVariable Long id,@Valid @RequestBody EmployeeInput i){return service.update(id,i);}@PatchMapping("/{id}/status")@PreAuthorize("hasAnyRole('ADMIN','HR')")EmployeeView status(@PathVariable Long id,@Valid @RequestBody StatusUpdate i){return service.status(id,i);}@GetMapping("/{id}/team")@PreAuthorize("hasAnyRole('ADMIN','HR','MANAGER')")Page<EmployeeView> team(@PathVariable Long id,Authentication a,@PageableDefault(sort="lastName")Pageable p){return service.team(id,a,p);}}
